SECTION_23 = '# =================================================================================\n# 2. إشعارات النواقص (Threshold Alerts - Reorder Point)\n# =================================================================================\n@router.get("/warehouse/alerts", response_model=List[WarehouseAlertItem], status_code=200)\nasync def get_warehouse_alerts(\n    location_id: int,\n    db: AsyncSession = Depends(get_db),\n    current_admin: Driver = Depends(get_current_admin)\n):\n    company_id = current_admin.company_id\n\n    stmt_location = select(InventoryLocation.id).filter_by(\n        id=location_id,\n        company_id=company_id,\n        location_type=\'WAREHOUSE\',\n        is_active=True\n    )\n    if (await db.execute(stmt_location)).scalar_one_or_none() is None:\n        raise HTTPException(\n            status_code=404,\n            detail="المستودع غير موجود أو لا يتبع شركتك."\n        )\n\n    inventory_subq = select(\n        InventoryBalance.product_variant_id,\n        func.sum(InventoryBalance.on_hand_quantity).label(\'on_hand_packs\'),\n        func.sum(InventoryBalance.reserved_quantity).label(\'reserved_packs\')\n    ).filter_by(\n        company_id=company_id,\n        location_id=location_id,\n        stock_status=\'AVAILABLE\'\n    ).group_by(\n        InventoryBalance.product_variant_id\n    ).subquery()\n\n    stmt = select(\n        ProductVariant.id,\n        ProductVariant.variant_name,\n        InventoryStockPolicy.minimum_quantity,\n        (\n            func.coalesce(inventory_subq.c.on_hand_packs, 0)\n            - func.coalesce(inventory_subq.c.reserved_packs, 0)\n        ).label(\'free_packs\')\n    ).join(\n        InventoryStockPolicy,\n        and_(\n            InventoryStockPolicy.company_id == ProductVariant.company_id,\n            InventoryStockPolicy.product_variant_id == ProductVariant.id,\n            InventoryStockPolicy.location_id == location_id,\n            InventoryStockPolicy.is_active.is_(True)\n        )\n    ).outerjoin(\n        inventory_subq,\n        inventory_subq.c.product_variant_id == ProductVariant.id\n    ).filter(\n        ProductVariant.company_id == company_id,\n        ProductVariant.is_active.is_(True),\n        InventoryStockPolicy.minimum_quantity > 0,\n        (\n            func.coalesce(inventory_subq.c.on_hand_packs, 0)\n            - func.coalesce(inventory_subq.c.reserved_packs, 0)\n        ) <= InventoryStockPolicy.minimum_quantity\n    ).order_by(\n        ProductVariant.variant_name.asc()\n    )\n\n    rows = (await db.execute(stmt)).all()\n\n    return [\n        {\n            "product_variant_id": variant_id,\n            "product_name": variant_name,\n            "current_total_packs": int(free_packs or 0),\n            "min_threshold_packs": int(minimum_quantity),\n        }\n        for variant_id, variant_name, minimum_quantity, free_packs in rows\n    ]\n\n\n# =================================================================================\n# 3. جلب حالة المستودع بالكامل من المحرك الموحد\n# =================================================================================\n@router.get("/warehouse/inventory", response_model=List[WarehouseInventoryItem], status_code=200)\nasync def get_warehouse_inventory(\n    location_id: int,\n    db: AsyncSession = Depends(get_db),\n    current_admin: Driver = Depends(get_current_admin)\n):\n    company_id = current_admin.company_id\n\n    try:\n        stmt_location = select(InventoryLocation.id).filter_by(\n            id=location_id,\n            company_id=company_id,\n            location_type=\'WAREHOUSE\',\n            is_active=True\n        )\n        if (await db.execute(stmt_location)).scalar_one_or_none() is None:\n            raise HTTPException(\n                status_code=404,\n                detail="المستودع غير موجود أو لا يتبع شركتك."\n            )\n\n        warehouse_available_subq = select(\n            InventoryBalance.product_variant_id,\n            func.sum(InventoryBalance.on_hand_quantity).label(\'warehouse_on_hand\'),\n            func.sum(InventoryBalance.reserved_quantity).label(\'warehouse_reserved\')\n        ).filter_by(\n            company_id=company_id,\n            location_id=location_id,\n            stock_status=\'AVAILABLE\'\n        ).group_by(\n            InventoryBalance.product_variant_id\n        ).subquery()\n\n        warehouse_damaged_subq = select(\n            InventoryBalance.product_variant_id,\n            func.sum(InventoryBalance.on_hand_quantity).label(\'damaged_packs\')\n        ).filter_by(\n            company_id=company_id,\n            location_id=location_id,\n            stock_status=\'DAMAGED\'\n        ).group_by(\n            InventoryBalance.product_variant_id\n        ).subquery()\n\n        # السيارة تُنسب إلى آخر خط سير معروف لها، حتى تبقى الحمولة النائمة\n        # محسوبة مع مستودع المصدر الأخير بعد إغلاق الجولة.\n        latest_vehicle_route_subq = select(\n            DispatchRoute.vehicle_id,\n            func.max(DispatchRoute.id).label(\'latest_route_id\')\n        ).filter(\n            DispatchRoute.company_id == company_id,\n            DispatchRoute.vehicle_id.isnot(None)\n        ).group_by(\n            DispatchRoute.vehicle_id\n        ).subquery()\n\n        vehicle_ids_for_warehouse = select(\n            DispatchRoute.vehicle_id\n        ).join(\n            latest_vehicle_route_subq,\n            and_(\n                latest_vehicle_route_subq.c.latest_route_id == DispatchRoute.id,\n                latest_vehicle_route_subq.c.vehicle_id == DispatchRoute.vehicle_id\n            )\n        ).filter(\n            DispatchRoute.company_id == company_id,\n            DispatchRoute.source_location_id == location_id,\n            DispatchRoute.vehicle_id.isnot(None)\n        )\n\n        vehicle_inventory_subq = select(\n            InventoryBalance.product_variant_id,\n            func.sum(InventoryBalance.on_hand_quantity).label(\'vehicle_packs\')\n        ).join(\n            InventoryLocation,\n            and_(\n                InventoryLocation.company_id == InventoryBalance.company_id,\n                InventoryLocation.id == InventoryBalance.location_id\n            )\n        ).filter(\n            InventoryBalance.company_id == company_id,\n            InventoryBalance.stock_status == \'AVAILABLE\',\n            InventoryLocation.company_id == company_id,\n            InventoryLocation.location_type == \'VEHICLE\',\n            InventoryLocation.is_active.is_(True),\n            InventoryLocation.vehicle_id.in_(vehicle_ids_for_warehouse)\n        ).group_by(\n            InventoryBalance.product_variant_id\n        ).subquery()\n\n        policy_subq = select(\n            InventoryStockPolicy.product_variant_id,\n            InventoryStockPolicy.minimum_quantity\n        ).filter_by(\n            company_id=company_id,\n            location_id=location_id,\n            is_active=True\n        ).subquery()\n\n        stmt = select(\n            ProductVariant,\n            warehouse_available_subq.c.warehouse_on_hand,\n            warehouse_available_subq.c.warehouse_reserved,\n            warehouse_damaged_subq.c.damaged_packs,\n            vehicle_inventory_subq.c.vehicle_packs,\n            policy_subq.c.minimum_quantity\n        ).outerjoin(\n            warehouse_available_subq,\n            warehouse_available_subq.c.product_variant_id == ProductVariant.id\n        ).outerjoin(\n            warehouse_damaged_subq,\n            warehouse_damaged_subq.c.product_variant_id == ProductVariant.id\n        ).outerjoin(\n            vehicle_inventory_subq,\n            vehicle_inventory_subq.c.product_variant_id == ProductVariant.id\n        ).outerjoin(\n            policy_subq,\n            policy_subq.c.product_variant_id == ProductVariant.id\n        ).filter(\n            ProductVariant.company_id == company_id,\n            or_(\n                ProductVariant.is_active.is_(True),\n                func.coalesce(warehouse_available_subq.c.warehouse_on_hand, 0) > 0,\n                func.coalesce(warehouse_damaged_subq.c.damaged_packs, 0) > 0,\n                func.coalesce(vehicle_inventory_subq.c.vehicle_packs, 0) > 0\n            )\n        ).order_by(\n            ProductVariant.variant_name.asc()\n        )\n\n        rows = (await db.execute(stmt)).all()\n\n        result = []\n        for (\n            variant,\n            warehouse_on_hand,\n            warehouse_reserved,\n            damaged_packs,\n            vehicle_packs,\n            minimum_quantity,\n        ) in rows:\n            on_hand = int(warehouse_on_hand or 0)\n            reserved = int(warehouse_reserved or 0)\n            free_packs = on_hand - reserved\n            vehicle_total = int(vehicle_packs or 0)\n            damaged = int(damaged_packs or 0)\n\n            if free_packs < 0:\n                raise RuntimeError(\n                    f"Inventory invariant violated for product_variant_id={variant.id}: "\n                    "reserved quantity exceeds on-hand quantity."\n                )\n\n            ppc = int(variant.packs_per_carton or 1)\n            total_physical_available = on_hand + vehicle_total\n\n            result.append({\n                "id": variant.id,\n                "name": variant.variant_name,\n                "sku": variant.sku,\n                "packs_per_carton": ppc,\n                "available_packs": free_packs,\n                "reserved_packs": reserved,\n                "total_packs": total_physical_available,\n                "damaged_packs": damaged,\n                "available_cartons": free_packs // ppc,\n                "available_loose_packs": free_packs % ppc,\n                "min_threshold": int(minimum_quantity or 0),\n            })\n\n        return result\n\n    except HTTPException:\n        raise\n    except Exception as e:\n        logger.error(f"خطأ في العملية: {str(e)}", exc_info=True)\n        raise HTTPException(\n            status_code=500,\n            detail="حدث خطأ داخلي في الخادم أثناء جلب الجرد."\n        )\n\n\n'
SECTION_67 = '# =================================================================================\n# 6. جلب قائمة المنتجات فقط (للقوائم المنسدلة Dropdowns)\n# =================================================================================\n@router.get("/product_variants/simple", response_model=List[SimpleProductVariantItem], status_code=200)\nasync def get_simple_product_variants(\n    db: AsyncSession = Depends(get_db),\n    current_admin: Driver = Depends(get_current_admin)\n):\n    stmt = select(ProductVariant).filter_by(\n        company_id=current_admin.company_id,\n        is_active=True\n    ).order_by(\n        ProductVariant.variant_name.asc()\n    )\n    variants = (await db.execute(stmt)).scalars().all()\n\n    return [{\n        "id": v.id,\n        "name": v.variant_name,\n        "packs_per_carton": int(v.packs_per_carton or 1),\n    } for v in variants]\n\n\n# =================================================================================\n# 7. إضافة منتج جديد لكتالوج الشركة\n# =================================================================================\n@router.post("/warehouse/product_variants", status_code=201)\nasync def add_product_variant(\n    payload: AddProductVariantRequest,\n    db: AsyncSession = Depends(get_db),\n    current_admin: Driver = Depends(get_current_admin)\n):\n    company_id = current_admin.company_id\n    clean_name = payload.variant_name.strip()\n    normalized_name = clean_name.lower()\n    clean_sku = payload.sku.strip() if payload.sku else None\n\n    duplicate_conditions = [\n        func.lower(ProductVariant.variant_name) == normalized_name\n    ]\n    if clean_sku:\n        duplicate_conditions.append(ProductVariant.sku == clean_sku)\n\n    stmt_exist = select(ProductVariant).filter(\n        ProductVariant.company_id == company_id,\n        or_(*duplicate_conditions)\n    )\n    existing = (await db.execute(stmt_exist)).scalars().first()\n\n    if existing:\n        if existing.variant_name.lower() == normalized_name:\n            raise HTTPException(\n                status_code=409,\n                detail=f"المنتج \'{payload.variant_name}\' موجود مسبقاً في شركتك."\n            )\n        raise HTTPException(\n            status_code=409,\n            detail=(\n                f"الباركود (SKU) \'{clean_sku}\' مستخدم بالفعل "\n                f"لمنتج آخر في شركتك ({existing.variant_name})."\n            )\n        )\n\n    try:\n        from models import UOM\n\n        # لا نربط الصنف بأول Product عشوائي؛ الكتالوج العام له Parent واضح وثابت.\n        stmt_product = select(Product).filter_by(\n            company_id=company_id,\n            base_name="منتجات عامة"\n        )\n        base_product = (await db.execute(stmt_product)).scalar_one_or_none()\n        if base_product is None:\n            base_product = Product(\n                company_id=company_id,\n                base_name="منتجات عامة"\n            )\n            db.add(base_product)\n            await db.flush()\n\n        stmt_uom = select(UOM.id).filter(\n            func.upper(UOM.code) == \'CARTON\'\n        ).limit(1)\n        uom_id = (await db.execute(stmt_uom)).scalar_one_or_none()\n\n        if uom_id is None:\n            stmt_any_uom = select(UOM.id).limit(1)\n            uom_id = (await db.execute(stmt_any_uom)).scalar_one_or_none()\n\n        if uom_id is None:\n            new_uom = UOM(name="كرتونة", code="CARTON")\n            db.add(new_uom)\n            await db.flush()\n            uom_id = new_uom.id\n\n        new_variant = ProductVariant(\n            company_id=company_id,\n            product_id=base_product.id,\n            base_uom_id=uom_id,\n            variant_name=clean_name,\n            sku=clean_sku,\n            price_per_carton=payload.price_per_carton,\n            packs_per_carton=payload.packs_per_carton,\n            price_per_pack=payload.price_per_pack,\n            default_max_samples_per_day=payload.default_max_samples_per_day or 0,\n            is_active=True\n        )\n        db.add(new_variant)\n        await db.flush()\n\n        stmt_warehouses = select(InventoryLocation.id).filter_by(\n            company_id=company_id,\n            location_type=\'WAREHOUSE\',\n            is_active=True\n        ).order_by(\n            InventoryLocation.id.asc()\n        )\n        warehouse_ids = (await db.execute(stmt_warehouses)).scalars().all()\n\n        minimum_quantity = int(payload.min_threshold_packs or 0)\n\n        # لا نسقط حد النقص بصمت إذا استُدعي الـ API قبل فتح شاشة المستودع لأول مرة.\n        if not warehouse_ids:\n            stmt_provision = pg_insert(InventoryLocation).values(\n                company_id=company_id,\n                name="المستودع الرئيسي",\n                code="WH-MAIN",\n                location_type=\'WAREHOUSE\',\n                is_active=True\n            ).on_conflict_do_nothing(\n                index_elements=[\'company_id\', \'code\']\n            )\n            await db.execute(stmt_provision)\n\n            stmt_warehouses = select(InventoryLocation.id).filter_by(\n                company_id=company_id,\n                location_type=\'WAREHOUSE\',\n                is_active=True\n            ).order_by(\n                InventoryLocation.id.asc()\n            )\n            warehouse_ids = (await db.execute(stmt_warehouses)).scalars().all()\n\n        if not warehouse_ids:\n            raise HTTPException(\n                status_code=409,\n                detail=(\n                    "لا يوجد مستودع فعال يمكن ربط سياسة حد النقص به. "\n                    "فعّل مستودعاً أولاً ثم أعد إضافة المنتج."\n                )\n            )\n\n        for warehouse_id in warehouse_ids:\n            db.add(InventoryStockPolicy(\n                company_id=company_id,\n                location_id=warehouse_id,\n                product_variant_id=new_variant.id,\n                minimum_quantity=minimum_quantity,\n                target_quantity=None,\n                is_active=True\n            ))\n\n        await db.commit()\n\n        return {\n            "message": f"تم إضافة المنتج \'{new_variant.variant_name}\' بنجاح.",\n            "product_id": new_variant.id\n        }\n\n    except HTTPException:\n        await db.rollback()\n        raise\n    except IntegrityError as e:\n        await db.rollback()\n        logger.error(f"خطأ في العملية: {str(e)}", exc_info=True)\n        raise HTTPException(\n            status_code=409,\n            detail=(\n                "مرفوض: تعارض في قاعدة البيانات. "\n                "قد يكون اسم المنتج أو الباركود مسجلاً مسبقاً للتو."\n            )\n        )\n    except Exception as e:\n        await db.rollback()\n        logger.error(f"خطأ في العملية: {str(e)}", exc_info=True)\n        raise HTTPException(\n            status_code=500,\n            detail="حدث خطأ داخلي في الخادم أثناء حفظ المنتج."\n        )\n\n\n'
START_23 = '# =================================================================================\n# 2. إشعارات النواقص (Threshold Alerts - Reorder Point)\n# =================================================================================\n'
END_23 = '# =================================================================================\n# 4. جلب سجل حركات المستودع (Ledger) - الدفتر غير القابل للمسح\n# =================================================================================\n'
START_67 = '# =================================================================================\n# 6. جلب قائمة المنتجات فقط (للقوائم المنسدلة Dropdowns)\n# =================================================================================\n'
END_67 = '# =================================================================================\n# 8. تعديل وإرجاع حركات المستودع (التصحيح العكسي) - Reversal \n# =================================================================================\n'


def git_blob_sha(data: bytes) -> str:
    header = f"blob {len(data)}\0".encode("ascii")
    return hashlib.sha1(header + data).hexdigest()


def replace_section(text: str, start: str, end: str, replacement: str) -> str:
    start_index = text.find(start)
    if start_index < 0:
        raise RuntimeError("لم يتم العثور على بداية القسم المطلوب.")
    end_index = text.find(end, start_index)
    if end_index < 0:
        raise RuntimeError("لم يتم العثور على نهاية القسم المطلوب.")
    return text[:start_index] + replacement + text[end_index:]


def main() -> None:
    if not TARGET.exists():
        raise SystemExit(f"ERROR: الملف غير موجود: {TARGET}")

    raw = TARGET.read_bytes()
    uses_crlf = b"\r\n" in raw

    normalized_raw = raw.replace(b"\r\n", b"\n").replace(b"\r", b"\n")
    current_sha = git_blob_sha(normalized_raw)

    if current_sha != EXPECTED_GIT_BLOB_SHA:
        raise SystemExit(
            "ERROR: محتوى warehouse.py مختلف فعلياً عن النسخة التي بُني عليها الباتش.\n"
            f"Expected normalized Git blob SHA: {EXPECTED_GIT_BLOB_SHA}\n"
            f"Current  normalized Git blob SHA: {current_sha}\n"
            "لم يتم تعديل أي شيء."
        )

    text = normalized_raw.decode("utf-8")
    if OLD_IMPORTS not in text:
        raise SystemExit("ERROR: كتلة imports المتوقعة غير موجودة. لم يتم تعديل أي شيء.")

    text = text.replace(OLD_IMPORTS, NEW_IMPORTS, 1)
    text = replace_section(text, START_23, END_23, SECTION_23)
    text = replace_section(text, START_67, END_67, SECTION_67)

    output_raw = text.encode("utf-8")
    if uses_crlf:
        output_raw = output_raw.replace(b"\n", b"\r\n")

    temp = TARGET.with_suffix(".py.phase1.tmp")
    temp.write_bytes(output_raw)
    temp.replace(TARGET)

    new_raw = TARGET.read_bytes()
    print("WAREHOUSE_PHASE1_V2_APPLIED_OK")
    print(f"New Git blob SHA: {git_blob_sha(new_raw)}")
    print("Changed: imports + alerts + live inventory + simple products + product creation/policies")
    print("Next: python -m py_compile wa_backend/api/warehouse.py")


if __name__ == "__main__":
    main()
